#!/usr/bin/env bash\nset -euo pipefail\n\n# Create a temporary directory for the mock event file\ntmpdir=$(mktemp -d)\nevent_file="$tmpdir/event.json"\ncat >"$event_file" <<'EOF'\n{\n  "pull_request": {\n    "title": "Fix critical bug in parser"\n  }\n}\nEOF\n\nexport GITHUB_EVENT_PATH="$event_file"\n\n# Run the labeler script\noutput=$(bash "$(dirname \"$0\")/../src/labeler.sh")\nexpected="::add-labels::bug"\n\nif [[ "$output" == "$expected" ]]; then\n  echo "PASS"\n  exit 0\nelse\n  echo "FAIL: expected $expected but got $output"\n  exit 1\nfi
